/* 文档图标渲染：与文件树弹窗一致（思源内置图标名→SVG、路径→emojis 图片、十六进制→Emoji、兜底原样显示）。
   定义为模块级函数，避免依赖 this/plugin 引用在不同作用域下取不到的问题。 */
function renderDocIconHtml(icon, def) {
    const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    const wrap = (inner) => `<span class="north-luna-doc-tree-icon">${inner}</span>`;
    if (!icon) return wrap(def);
    if (/^icon[A-Z]/.test(icon)) {
        return `<span class="north-luna-doc-tree-icon"><svg class="icon"><use xlink:href="#${esc(icon)}"></use></svg></span>`;
    }
    if (/[\\/.]/.test(icon)) {
        return `<img class="north-luna-doc-tree-icon" src="/emojis/${esc(icon)}" alt="">`;
    }
    const parts = icon.split('-').filter(Boolean);
    if (parts.length && parts.every(c => /^[0-9a-fA-F]{1,8}$/.test(c))) {
        try {
            const ch = parts.map(c => String.fromCodePoint(parseInt(c, 16))).join('');
            if (ch) return wrap(ch);
        } catch (e) {}
    }
    return wrap(esc(icon));
}

/* ============================================================
 * 视图定义
 * ============================================================ */

/* 清风视图：热力图 cells（基于真实 breezeNotes 数据生成最近 12 周 84 天）
   网格 7 行 × 12 列 = 84 格；最右列 col 11 对应当前周（最右下 cell ≈ today）；
   每个 cell 写入 data-lumina-tip="X条 M月D日"（无笔记时仅写日期），
   由全局 _bindBreezeHeatmapEvents 监听 mouseover 显示暗色 tooltip */
function buildBreezeHeatmap(notes) {
    notes = notes || [];
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    /* 统计每天笔记数（time 格式 YYYY-MM-DD HH:MM） */
    const dayCounts = {};
    notes.forEach(n => {
        const d = (n.time || '').slice(0, 10);
        if (d) dayCounts[d] = (dayCounts[d] || 0) + 1;
    });
    const p2 = n => String(n).padStart(2, '0');
    const cells = [];
    for (let row = 0; row < 7; row++) {
        for (let col = 0; col < 12; col++) {
            /* 与轻语一致：dayIndex = col*7 + row，日期 = today - (83 - dayIndex)；
               最右下 cell (col=11,row=6) 的 dayIndex=83 → 正好是 today（不受星期几影响） */
            const dayIndex = col * 7 + row;
            const cellDate = new Date(today);
            cellDate.setDate(today.getDate() - (83 - dayIndex));
            const ymd = cellDate.getFullYear() + '-' + p2(cellDate.getMonth() + 1) + '-' + p2(cellDate.getDate());
            const count = dayCounts[ymd] || 0;
            let level = 0;
            if (count >= 1) level = 1;
            if (count >= 3) level = 2;
            if (count >= 5) level = 3;
            if (count >= 7) level = 4;
            const tip = count > 0
                ? count + '条 ' + (cellDate.getMonth() + 1) + '月' + cellDate.getDate() + '日'
                : (cellDate.getMonth() + 1) + '月' + cellDate.getDate() + '日';
            cells.push('<div class="north-breeze-heatmap-grid-cell level-' + level + '" data-date="' + ymd + '" data-lumina-tip="' + breezeEsc(tip) + '"></div>');
        }
    }
    return cells.join('');
}
/* 清风视图：热力图月份标签（与轻语 generateHeatmapMonths 一致）
   覆盖最近 3 个月（含本月），均匀落在 12 列的 2/4、6/8、10/12 区间居中 */
function buildBreezeHeatmapMonths() {
    const today = new Date();
    const monthNames = ['一月', '二月', '三月', '四月', '五月', '六月', '七月', '八月', '九月', '十月', '十一月', '十二月'];
    const months = [];
    for (let i = 2; i >= 0; i--) {
        const d = new Date(today);
        d.setMonth(d.getMonth() - i);
        months.push(d.getMonth());
    }
    /* 二月/三月/四月 这类占位仅用于对齐 12 列栅格：本月通常在最右列，
       向左每跨 4 列标注一个更早的月份，保持与轻语同样的视觉节律 */
    const spans = [
        { start: 2, end: 4 },
        { start: 6, end: 8 },
        { start: 10, end: 12 }
    ];
    let html = '';
    for (let i = 0; i < months.length; i++) {
        html += '<span style="grid-column: ' + spans[i].start + ' / ' + spans[i].end + '; text-align: center;">' + monthNames[months[i]] + '</span>';
    }
    return html;
}

/* 清风视图：笔记列表（由插件本地数据驱动，不调用 API） */
function breezeEsc(s) {
    if (s == null) return '';
    return String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
}
/* 有标题的卡片日期格式：2026年07月26日 星期日 20:48 */
function breezeFormatTitleDate(timeStr) {
    if (!timeStr) return '';
    const d = new Date(String(timeStr).replace(/-/g, '/'));
    if (isNaN(d.getTime())) return breezeEsc(timeStr);
    const weekdays = ['日', '一', '二', '三', '四', '五', '六'];
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    const w = '星期' + weekdays[d.getDay()];
    const h = String(d.getHours()).padStart(2, '0');
    const min = String(d.getMinutes()).padStart(2, '0');
    return y + '年' + m + '月' + day + '日 ' + w + ' ' + h + ':' + min;
}
/* 文件扩展名 → 徽章背景色（与轻语 _fileExtColor 同源配色表） */
function breezeFileExtColor(ext) {
    const colors = {
        PDF: '#e74c3c', DOC: '#2b5797', DOCX: '#2b5797',
        XLS: '#217346', XLSX: '#217346', PPT: '#d04526', PPTX: '#d04526',
        ZIP: '#9b59b6', RAR: '#9b59b6', '7Z': '#9b59b6', GZ: '#9b59b6',
        TXT: '#95a5a6', MD: '#3498db', JSON: '#e67e22', XML: '#e67e22',
        CSV: '#27ae60', LOG: '#636e72', EXE: '#e74c3c', DMG: '#636e72',
        APK: '#27ae60', ISO: '#636e72', TORRENT: '#16a085',
        HTML: '#e34f26', CSS: '#2965f1', JS: '#f7df1e', TS: '#3178c6',
    };
    return colors[ext] || '#1abc9c';
}
/* 笔记卡片"更多"菜单：克隆轻语 showNoteMenu 结构，类名换成 north-breeze-*。
   对齐轻语：
   - position:fixed 挂在 document.body，z-index 99999
   - 屏幕底部空间不足时自动翻转到 trigger 上方
   - outside-click 关闭（用 setTimeout(0) 挂一次性 document 监听，避免和触发本次 click 的事件冲突）
   - 菜单项图标用思源笔记内置 iconfont（与轻语一致）：<svg class="icon"><use xlink:href="#iconXxx"></use></svg>
   - icon 对照：置顶 iconPin / 编辑 iconEdit / 复制 iconCopy / 分享 iconSpreadOdd /
                 批注 iconMark / 修改时间 iconClock / 插入今日日记 iconSparkles /
                 添加到朋友圈 iconGlobe / 归档 iconInbox / 删除 iconTrashcan(14×14, 红色)
   按用户当前要求：菜单项**功能暂不实现**，点击只关闭菜单 + 控制台 log，后续按需补。 */
function showBreezeNoteMenu(id, triggerEl, storage, plugin) {
    // 移除已存在的菜单（保证单实例）
    const existing = document.querySelector('.north-breeze-note-menu-dropdown');
    if (existing) existing.remove();
    // 找对应笔记（菜单项判断需要，比如置顶/归档文案）
    const notes = ((storage || {}).breezeNotes) || [];
    const note = notes.find((n) => n.id === id);
    if (!note) return;
    const isPinned = !!note.pinned;
    const isArchived = !!note.archived;
    // 工具：渲染思源内置 icon 项
    const iconItem = (action, iconId, text, danger) =>
        '<div class="north-breeze-menu-item' + (danger ? ' danger' : '') + '" data-action="' + action + '">' +
            '<span class="north-breeze-menu-icon"><svg class="icon" style="width:16px;height:16px;"><use xlink:href="#' + iconId + '"></use></svg></span>' +
            '<span class="north-breeze-menu-text">' + text + '</span>' +
        '</div>';
    const iconItemSmall = (action, iconId, text, danger) =>
        '<div class="north-breeze-menu-item' + (danger ? ' danger' : '') + '" data-action="' + action + '">' +
            '<span class="north-breeze-menu-icon"><svg class="icon" style="width:14px;height:14px;"><use xlink:href="#' + iconId + '"></use></svg></span>' +
            '<span class="north-breeze-menu-text">' + text + '</span>' +
        '</div>';
    const menu = document.createElement('div');
    menu.className = 'north-breeze-note-menu-dropdown';
    menu.innerHTML =
        iconItem('pin',         'iconPin',       isPinned ? '取消置顶' : '置顶') +
        iconItem('edit',        'iconEdit',      '编辑') +
        '<div class="north-breeze-menu-divider"></div>' +
        iconItem('copy',        'iconCopy',      '复制') +
        iconItem('share',       'iconSpreadOdd', '分享') +
        iconItem('comment',     'iconMark',      '批注') +
        iconItem('change-time', 'iconClock',     '修改时间') +
        iconItem('append-daily-note', 'iconSparkles', '插入今日日记') +
        '<div class="north-breeze-menu-divider"></div>' +
        iconItem('add-to-moments', 'iconGlobe',  '添加到朋友圈') +
        iconItem('archive',     'iconInbox',     isArchived ? '取消归档' : '归档') +
        iconItemSmall('delete', 'iconTrashcan',  '删除', true);
    document.body.appendChild(menu);
    // 定位：fixed；底部空间不足则向上弹；左侧做视口边界保护
    const rect = triggerEl.getBoundingClientRect();
    menu.style.position = 'fixed';
    menu.style.zIndex = '99999';
    const menuHeight = menu.offsetHeight;
    const menuWidth = menu.offsetWidth;
    const viewportHeight = window.innerHeight;
    const viewportWidth = window.innerWidth;
    if (rect.bottom + 4 + menuHeight > viewportHeight) {
        menu.style.top = (rect.top - menuHeight - 4) + 'px';
    } else {
        menu.style.top = (rect.bottom + 4) + 'px';
    }
    // 菜单向左展开 120px（对齐轻语），再做边界保护：不能超出屏幕右侧、不能小于 4px
    let left = rect.left - 120;
    if (left + menuWidth > viewportWidth - 4) left = viewportWidth - menuWidth - 4;
    if (left < 4) left = 4;
    menu.style.left = left + 'px';
    // 菜单项 click：实现置顶（pin），其余菜单项暂留 console.log 接口
    menu.addEventListener('click', (ev) => {
        const item = ev.target.closest('.north-breeze-menu-item');
        if (!item) return;
        const action = item.dataset.action;
        menu.remove();
        switch (action) {
            case 'pin': {
                // note 是 storage.breezeNotes 中同一引用，直接改字段后持久化即可
                if (note) {
                    note.pinned = !note.pinned;
                    if (plugin && plugin.saveData) {
                        plugin.saveData(RECORDS_STORAGE, storage).catch(() => {});
                    }
                }
                // 重渲染：让置顶项排到前面
                if (plugin && plugin._siyuTab && typeof plugin._siyuTab.render === 'function') {
                    plugin._siyuTab.render();
                }
                break;
            }
            case 'edit':
                // 卡片内联编辑（复刻轻语）：把卡片内容区就地替换为编辑框
                editBreezeNote(id, storage, plugin);
                break;
            case 'copy':
                // 复制：文字 → 空行 → 资源 Markdown，去 leading / 对齐思源路径
                {
                    let text = (note && note.content) || '';
                    let resources = '';
                    (note.images || []).forEach(img => {
                        let url = img.path || img || '';
                        if (url.startsWith('/')) url = url.slice(1);
                        if (url) resources += '\n![](' + url + ')';
                    });
                    (note.files || []).forEach(f => {
                        let url = f.path || '';
                        if (url.startsWith('/')) url = url.slice(1);
                        if (url) resources += '\n[' + (f.name || '附件') + '](' + url + ')';
                    });
                    if (resources) text += '\n' + resources;
                    const finish = () => { try { showMessage('已复制到剪贴板'); } catch (_) {} };
                    if (navigator.clipboard && navigator.clipboard.writeText) {
                        navigator.clipboard.writeText(text).then(finish).catch(() => {
                            const ta = document.createElement('textarea');
                            ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
                            document.body.appendChild(ta); ta.select();
                            try { document.execCommand('copy'); } catch (_) {}
                            document.body.removeChild(ta); finish();
                        });
                    } else {
                        const ta = document.createElement('textarea');
                        ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
                        document.body.appendChild(ta); ta.select();
                        try { document.execCommand('copy'); } catch (_) {}
                        document.body.removeChild(ta); finish();
                    }
                }
                break;
            case 'change-time':
                // 修改时间（复刻轻语时间选择器体验）：弹窗选时间 → 改 note.time → 持久化 + 重排
                changeBreezeNoteTime(id, storage, plugin);
                break;
            case 'add-to-moments':
                // 添加到朋友圈（复刻轻语 addShuoshuoToMoments）：把笔记转成一条朋友圈动态
                addBreezeNoteToMoments(id, storage, plugin);
                break;
            case 'append-daily-note':
                // 插入今日日记：复用通用同步方法
                (async () => {
                    if (!note) return;
                    const settings = plugin.data[SETTINGS_STORAGE]?.settings || {};
                    const result = await plugin._syncToDailyNote({
                        content: note.content,
                        images: note.images,
                        files: note.files,
                        time: note.time,
                        source: 'breeze'
                    });
                    if (typeof showMessage === 'function') showMessage(result.message);
                })();
                break;
            case 'delete':
                // 删除笔记并清理对应资源文件（带确认提示）
                if (note) {
                    const doDelete = () => {
                        // 清理图片
                        (note.images || []).forEach(img => {
                            if (plugin && plugin.deletePluginImage) plugin.deletePluginImage(img);
                        });
                        // 清理文件
                        (note.files || []).forEach(f => {
                            if (plugin && plugin.deletePluginImage && f.path) plugin.deletePluginImage(f.path);
                        });
                        // 从数组中移除
                        const notes = ((storage || {}).breezeNotes) || [];
                        const idx = notes.indexOf(note);
                        if (idx >= 0) notes.splice(idx, 1);
                        if (plugin && plugin.saveData) {
                            plugin.saveData(RECORDS_STORAGE, storage).catch(() => {});
                        }
                        if (plugin && plugin._siyuTab && typeof plugin._siyuTab.render === 'function') {
                            plugin._siyuTab.render();
                        }
                    };
                    if (confirm) {
                        confirm('删除笔记', '确定要删除这条清风笔记吗？\n此操作不可恢复。', doDelete);
                    } else {
                        doDelete();
                    }
                }
                break;
            case 'comment':
                // 批注（复刻轻语）：提取原文预览 → 滚到输入框 → 插入 [MEMO:id] 引用 → 聚焦输入框
                {
                    /* 查找输入框：主视图优先 → Dock 侧边栏回退 → 找不到才报错 */
                    let input = null;
                    if (plugin && plugin._siyuTab && plugin._siyuTab.container) {
                        input = plugin._siyuTab.container.querySelector('#breeze-input');
                    }
                    if (!input && plugin && plugin._breezeDockEl) {
                        input = plugin._breezeDockEl.querySelector('#north-breeze-dock-input');
                    }
                    if (!input) {
                        console.log('[清风批注] 找不到 #breeze-input 或 Dock 输入框');
                        break;
                    }
                    /* 预览：纯文本，去标签，截 60 字 */
                    let preview = ((note && note.content) || '').replace(/<[^>]*>/g, '');
                    preview = preview.replace(/#[^\s\d][^\s]*(?:\/[^\s]+)*/g, '').trim().replace(/\s+/g, ' ').slice(0, 60);
                    if (preview.length >= 60) preview += '…';
                    /* 展开发送区域（如果侧栏折叠了） */
                    const box = input.closest('.north-breeze-input-box');
                    if (box) box.classList.add('focused');
                    input.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    /* 插入引用 */
                    const cur = input.value || '';
                    const insert = preview + ' [MEMO:' + id + ']';
                    if (cur) {
                        input.value = insert + '\n' + cur;
                        input.setSelectionRange(insert.length + 1, insert.length + 1);
                    } else {
                        input.value = insert + '\n';
                        input.setSelectionRange(insert.length + 1, insert.length + 1);
                    }
                    input.focus();
                    input.dispatchEvent(new Event('input'));
                }
                break;
            case 'share':
                // 分享 → 生成卡片图片
                shareBreezeNoteImage(id, storage, plugin);
                break;
            default:
                // eslint-disable-next-line no-console
                console.log('[清风] 笔记菜单点击:', action, '(id=' + id + ')，功能稍后实现');
        }
    });
    // outside-click 关闭：setTimeout(0) 推迟挂载，避开触发本次 click 的事件冒泡
    setTimeout(() => {
        const onDocClick = (ev) => {
            if (menu.contains(ev.target)) return;
            menu.remove();
            document.removeEventListener('click', onDocClick, true);
        };
        document.addEventListener('click', onDocClick, true);
    }, 0);
}
